#include <stdio.h>
#include <string.h>

int soundex_digit(char c) {
    switch (c) {
        case 'B':
        case 'F':
        case 'P':
        case 'V':
            return 1;
        case 'C':
        case 'G':
        case 'J':
        case 'K':
        case 'Q':
        case 'S':
        case 'X':
        case 'Z':
            return 2;
        case 'D':
        case 'T':
            return 3;
        case 'L':
            return 4;
        case 'M':
        case 'N':
            return 5;
        case 'R':
            return 6;
        default:
            return 0;
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("EMPTY\n");
        return 0;
    }

    char *str = argv[1];
    int len = strlen(str);
    char soundex_code[4] = {0};

    soundex_code[0] = str[0];

    int i;
    for (i = 1; i < len; i++) {
        char c = str[i];
        int digit = soundex_digit(c);
        if (digit != 0) {
            soundex_code[i % 3] = digit + '0';
        }
    }

    printf("%s\n", soundex_code);

    return 0;
}
